import { DatabaseSync } from "node:sqlite";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";

// One row per Auth0 user. Every query is keyed by `sub` taken from a verified
// access token — never by an id supplied in the request body or URL.
const SCHEMA = `
  CREATE TABLE IF NOT EXISTS users (
    sub        TEXT PRIMARY KEY,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
  CREATE TABLE IF NOT EXISTS user_preferences (
    sub        TEXT PRIMARY KEY REFERENCES users(sub) ON DELETE CASCADE,
    data       TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
`;

export function openDb(path) {
  if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec("PRAGMA foreign_keys = ON;");
  db.exec(SCHEMA);

  const insertUser = db.prepare("INSERT OR IGNORE INTO users (sub) VALUES (?)");
  const selectPrefs = db.prepare(
    "SELECT data, updated_at FROM user_preferences WHERE sub = ?",
  );
  const upsertPrefs = db.prepare(`
    INSERT INTO user_preferences (sub, data, updated_at)
    VALUES (?, ?, datetime('now'))
    ON CONFLICT(sub) DO UPDATE SET data = excluded.data, updated_at = excluded.updated_at
  `);

  return {
    getProfile(sub) {
      const row = selectPrefs.get(sub);
      return row ? { ...JSON.parse(row.data), updatedAt: row.updated_at } : null;
    },
    saveProfile(sub, profile) {
      insertUser.run(sub);
      upsertPrefs.run(sub, JSON.stringify(profile));
      return this.getProfile(sub);
    },
    close() {
      db.close();
    },
  };
}

// Validation for the grocery profile. Hand-rolled to keep dependencies small.
// Returns { value } on success or { errors } with one message per bad field.

export const DIETS = ["none", "vegetarian", "vegan", "pescatarian"];
export const COOKING_PREFS = ["any", "quick", "batch", "minimal-prep"];

export const DEFAULT_PROFILE = {
  budget: 100,
  householdSize: 1,
  shoppingDays: 7,
  diet: "none",
  cuisines: [],
  allergies: [],
  avoid: [],
  nutritionPrefs: [],
  cookingPref: "any",
  postalCode: "",
  pantry: [],
};

const MAX_LIST = 50;
const MAX_ITEM = 80;
// Canadian postal code or FSA (e.g. "N6G" or "N6G 1A1").
const POSTAL_RE = /^[A-Za-z]\d[A-Za-z](?:\s?\d[A-Za-z]\d)?$/;

function stringList(value, field, errors) {
  if (!Array.isArray(value)) {
    errors[field] = "must be an array of strings";
    return [];
  }
  if (value.length > MAX_LIST) {
    errors[field] = `at most ${MAX_LIST} entries`;
    return [];
  }
  const out = [];
  for (const item of value) {
    if (typeof item !== "string") {
      errors[field] = "must be an array of strings";
      return [];
    }
    const trimmed = item.trim();
    if (trimmed.length > MAX_ITEM) {
      errors[field] = `entries must be ${MAX_ITEM} characters or fewer`;
      return [];
    }
    if (trimmed && !out.some((x) => x.toLowerCase() === trimmed.toLowerCase())) {
      out.push(trimmed);
    }
  }
  return out;
}

function number(value, field, { min, max, integer }, errors) {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    errors[field] = "must be a number";
    return undefined;
  }
  if (integer && !Number.isInteger(value)) {
    errors[field] = "must be a whole number";
    return undefined;
  }
  if (value < min || value > max) {
    errors[field] = `must be between ${min} and ${max}`;
    return undefined;
  }
  return value;
}

function oneOf(value, field, allowed, errors) {
  if (!allowed.includes(value)) {
    errors[field] = `must be one of: ${allowed.join(", ")}`;
    return undefined;
  }
  return value;
}

export function validateProfile(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return { errors: { body: "must be a JSON object" } };
  }
  const errors = {};
  const known = new Set(Object.keys(DEFAULT_PROFILE));
  for (const key of Object.keys(input)) {
    if (!known.has(key)) errors[key] = "unknown field";
  }

  // Missing fields fall back to defaults so the client can send partial forms.
  const src = { ...DEFAULT_PROFILE, ...input };
  const value = {
    budget: number(src.budget, "budget", { min: 10, max: 2000 }, errors),
    householdSize: number(src.householdSize, "householdSize", { min: 1, max: 12, integer: true }, errors),
    shoppingDays: number(src.shoppingDays, "shoppingDays", { min: 1, max: 14, integer: true }, errors),
    diet: oneOf(src.diet, "diet", DIETS, errors),
    cuisines: stringList(src.cuisines, "cuisines", errors),
    allergies: stringList(src.allergies, "allergies", errors),
    avoid: stringList(src.avoid, "avoid", errors),
    nutritionPrefs: stringList(src.nutritionPrefs, "nutritionPrefs", errors),
    cookingPref: oneOf(src.cookingPref, "cookingPref", COOKING_PREFS, errors),
    postalCode: "",
    pantry: stringList(src.pantry, "pantry", errors),
  };

  if (typeof src.postalCode !== "string") {
    errors.postalCode = "must be a string";
  } else {
    const pc = src.postalCode.trim().toUpperCase();
    if (pc && !POSTAL_RE.test(pc)) errors.postalCode = "must be a Canadian postal code, e.g. N6G 1A1";
    value.postalCode = pc;
  }

  if (Object.keys(errors).length) return { errors };
  value.budget = Math.round(value.budget * 100) / 100;
  return { value };
}

import express from "express";
import cors from "cors";
import { auth, requiredScopes } from "express-oauth2-jwt-bearer";
import { validateProfile, DEFAULT_PROFILE } from "./profile.js";

export const SCOPES = {
  readProfile: "read:profile",
  writeProfile: "write:profile",
};

/**
 * Build the Express app.
 * @param {object} opts
 * @param {object} opts.authOptions  options for express-oauth2-jwt-bearer `auth()`
 *        (production: { issuerBaseURL, audience }; tests inject a local key).
 * @param {object} opts.db           store from openDb()
 * @param {string[]} [opts.corsOrigins]
 */
export function createApp({ authOptions, db, corsOrigins = [] }) {
  const app = express();
  app.disable("x-powered-by");
  app.use(cors({ origin: corsOrigins, allowedHeaders: ["Authorization", "Content-Type"] }));
  app.use(express.json({ limit: "32kb" }));

  app.get("/api/health", (_req, res) => res.json({ ok: true }));

  // Everything below requires a valid Auth0 access token for this API.
  const checkJwt = auth(authOptions);
  const api = express.Router();
  api.use(checkJwt);

  // The user id ALWAYS comes from the verified token, never from the request.
  const userSub = (req) => req.auth.payload.sub;

  api.get("/profile", requiredScopes(SCOPES.readProfile), (req, res) => {
    const profile = db.getProfile(userSub(req));
    res.json({ profile: profile ?? { ...DEFAULT_PROFILE }, saved: Boolean(profile) });
  });

  api.put("/profile", requiredScopes(SCOPES.writeProfile), (req, res) => {
    const { value, errors } = validateProfile(req.body);
    if (errors) return res.status(400).json({ error: "invalid_profile", fields: errors });
    const profile = db.saveProfile(userSub(req), value);
    res.json({ profile, saved: true });
  });

  app.use("/api", api);

  app.use("/api", (_req, res) => res.status(404).json({ error: "not_found" }));

  // Auth errors from express-oauth2-jwt-bearer carry a status (401/403).
  // Never echo token contents; just the error code.
  app.use((err, _req, res, _next) => {
    if (err.type === "entity.parse.failed") {
      return res.status(400).json({ error: "invalid_json" });
    }
    const status = err.status ?? err.statusCode ?? 500;
    if (status >= 500) console.error(err);
    res
      .status(status)
      .json({ error: status === 401 ? "unauthorized" : status === 403 ? "forbidden" : status >= 500 ? "server_error" : err.code ?? "error" });
  });

  return app;
}

import { createApp } from "./app.js";
import { openDb } from "./db.js";

const domain = process.env.AUTH0_DOMAIN ?? process.env.VITE_AUTH0_DOMAIN;
const audience = process.env.AUTH0_AUDIENCE ?? process.env.VITE_AUTH0_AUDIENCE;
const port = Number(process.env.API_PORT ?? 3001);

const missing = [
  !domain && "AUTH0_DOMAIN (or VITE_AUTH0_DOMAIN)",
  !audience && "AUTH0_AUDIENCE (or VITE_AUTH0_AUDIENCE)",
].filter(Boolean);
if (missing.length) {
  console.error(`Missing env: ${missing.join(", ")}. Add them to .env.local.`);
  process.exit(1);
}

const db = openDb(process.env.DB_PATH ?? "data/cartpilot.db");
const app = createApp({
  authOptions: {
    issuerBaseURL: `https://${domain}/`,
    audience,
    tokenSigningAlg: "RS256",
  },
  db,
  corsOrigins: (process.env.CORS_ORIGINS ?? "http://localhost:5173").split(","),
});

app.listen(port, () => {
  console.log(`CartPilot API on http://localhost:${port} (audience ${audience})`);
});

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { generateKeyPair, SignJWT } from "jose";
import { createApp } from "./app.js";
import { openDb } from "./db.js";

// Tests sign tokens with a local RSA key and hand the public key to the same
// express-oauth2-jwt-bearer middleware used in production (via `secret`),
// so signature, issuer, audience, expiry and scope checks all run for real.
const ISSUER = "https://test-tenant.example.com/";
const AUDIENCE = "https://cartpilot-api";
let server, base, privateKey, db;

before(async () => {
  const keys = await generateKeyPair("RS256");
  privateKey = keys.privateKey;
  db = openDb(":memory:");
  const app = createApp({
    authOptions: { issuer: ISSUER, audience: AUDIENCE, secret: keys.publicKey, tokenSigningAlg: "RS256" },
    db,
  });
  await new Promise((r) => (server = app.listen(0, r)));
  base = `http://127.0.0.1:${server.address().port}`;
});

after(() => {
  server.close();
  db.close();
});

const ALL = "read:profile write:profile";
function token(sub, { scope = ALL, aud = AUDIENCE, iss = ISSUER, key = privateKey, exp = "5m" } = {}) {
  return new SignJWT({ scope })
    .setProtectedHeader({ alg: "RS256" })
    .setSubject(sub)
    .setIssuer(iss)
    .setAudience(aud)
    .setIssuedAt()
    .setExpirationTime(exp)
    .sign(key);
}

async function call(method, path, { tok, body } = {}) {
  const res = await fetch(base + path, {
    method,
    headers: {
      ...(tok && { Authorization: `Bearer ${tok}` }),
      ...(body !== undefined && { "Content-Type": "application/json" }),
    },
    body: body === undefined ? undefined : typeof body === "string" ? body : JSON.stringify(body),
  });
  return { status: res.status, json: await res.json() };
}

const goodProfile = {
  budget: 100,
  householdSize: 1,
  shoppingDays: 7,
  diet: "none",
  cuisines: ["Korean", "Italian"],
  allergies: ["peanuts"],
  avoid: ["snacks", "sugary drinks"],
  nutritionPrefs: ["high protein"],
  cookingPref: "quick",
  postalCode: "n6g 1a1",
  pantry: ["rice", "soy sauce"],
};

test("health is public", async () => {
  assert.equal((await call("GET", "/api/health")).status, 200);
});

test("profile without a token is 401", async () => {
  assert.equal((await call("GET", "/api/profile")).status, 401);
  assert.equal((await call("PUT", "/api/profile", { body: goodProfile })).status, 401);
});

test("tokens with wrong audience, issuer, signer, or expired are 401", async () => {
  const { privateKey: otherKey } = await generateKeyPair("RS256");
  for (const tok of [
    await token("auth0|a", { aud: "https://other-api" }),
    await token("auth0|a", { iss: "https://evil.example.com/" }),
    await token("auth0|a", { key: otherKey }),
    await token("auth0|a", { exp: Math.floor(Date.now() / 1000) - 60 }),
  ]) {
    assert.equal((await call("GET", "/api/profile", { tok })).status, 401);
  }
});

test("missing scope is 403", async () => {
  const readOnly = await token("auth0|a", { scope: "read:profile" });
  assert.equal((await call("GET", "/api/profile", { tok: readOnly })).status, 200);
  assert.equal((await call("PUT", "/api/profile", { tok: readOnly, body: goodProfile })).status, 403);
});

test("new user gets defaults, can save, and reload", async () => {
  const tok = await token("auth0|alice");
  const first = await call("GET", "/api/profile", { tok });
  assert.equal(first.status, 200);
  assert.equal(first.json.saved, false);
  assert.equal(first.json.profile.budget, 100);

  const put = await call("PUT", "/api/profile", { tok, body: goodProfile });
  assert.equal(put.status, 200);
  assert.equal(put.json.profile.postalCode, "N6G 1A1");

  const again = await call("GET", "/api/profile", { tok });
  assert.equal(again.json.saved, true);
  assert.deepEqual(again.json.profile.pantry, ["rice", "soy sauce"]);
});

test("profiles are isolated per user; body cannot pick the user", async () => {
  const alice = await token("auth0|iso-alice");
  const bob = await token("auth0|iso-bob");
  await call("PUT", "/api/profile", { tok: alice, body: { ...goodProfile, budget: 150 } });
  // Bob tries to smuggle a sub in the body: rejected as an unknown field.
  const smuggle = await call("PUT", "/api/profile", { tok: bob, body: { ...goodProfile, sub: "auth0|iso-alice" } });
  assert.equal(smuggle.status, 400);
  const bobView = await call("GET", "/api/profile", { tok: bob });
  assert.equal(bobView.json.saved, false);
  const aliceView = await call("GET", "/api/profile", { tok: alice });
  assert.equal(aliceView.json.profile.budget, 150);
});

test("invalid profiles are rejected with field errors", async () => {
  const tok = await token("auth0|val");
  const bad = await call("PUT", "/api/profile", {
    tok,
    body: { budget: -5, householdSize: 2.5, diet: "carnivore", postalCode: "12345", avoid: "snacks" },
  });
  assert.equal(bad.status, 400);
  assert.deepEqual(Object.keys(bad.json.fields).sort(), ["avoid", "budget", "diet", "householdSize", "postalCode"]);

  const malformed = await call("PUT", "/api/profile", { tok, body: "{not json" });
  assert.equal(malformed.status, 400);
});

