// Review-cart logic shared by the server (authoritative) and the browser
// (instant feedback). Pure JavaScript, no Node or DOM imports.
//
// A selection per research item: { option, packages, removed }
//   option   index into [item.chosen, ...item.alternatives]
//   packages how many packs to buy (1–20)
//   removed  the user dropped this item
// Prices always come from the stored research, never from the client.

export const MAX_PACKAGES = 20;
const round2 = (x) => Math.round(x * 100) / 100;

export const optionsOf = (item) => (item?.chosen ? [item.chosen, ...(item.alternatives ?? [])] : []);

export function defaultSelection(item) {
  return { option: 0, packages: item?.chosen?.packages ?? 1, removed: false };
}

export function defaultSelections(research) {
  return research.items.map(defaultSelection);
}

/**
 * Validate and apply edits. Returns { selections } or { errors: [{ index, field, message }] }.
 * Edit shape: { index, name, option?, packages?, removed? }
 */
export function applyEdits(research, selections, edits) {
  const errors = [];
  if (!Array.isArray(edits) || edits.length === 0 || edits.length > 50) {
    return { errors: [{ field: "edits", message: "must be a list of 1–50 edits" }] };
  }
  const next = selections.map((s) => ({ ...s }));
  const allowed = new Set(["index", "name", "option", "packages", "removed"]);

  for (const edit of edits) {
    if (!edit || typeof edit !== "object" || Array.isArray(edit)) {
      errors.push({ field: "edit", message: "must be an object" });
      continue;
    }
    const { index } = edit;
    const err = (field, message) => errors.push({ index, field, message });
    for (const key of Object.keys(edit)) if (!allowed.has(key)) err(key, "unknown field");
    const item = Number.isInteger(index) ? research.items[index] : undefined;
    if (!item) {
      err("index", "no such item");
      continue;
    }
    if (edit.name !== item.name) {
      err("name", "doesn't match this item (the list may have changed; reload)");
      continue;
    }
    const sel = next[index];
    const opts = optionsOf(item);

    if (edit.option !== undefined) {
      if (!Number.isInteger(edit.option) || edit.option < 0 || edit.option >= opts.length) {
        err("option", `must be between 0 and ${Math.max(opts.length - 1, 0)}`);
      } else if (edit.option !== sel.option) {
        sel.option = edit.option;
        // A different product has a different pack size; start from its suggested count.
        if (edit.packages === undefined) sel.packages = opts[edit.option].packages ?? 1;
      }
    }
    if (edit.packages !== undefined) {
      if (!Number.isInteger(edit.packages) || edit.packages < 1 || edit.packages > MAX_PACKAGES) {
        err("packages", `must be a whole number from 1 to ${MAX_PACKAGES}`);
      } else {
        sel.packages = edit.packages;
      }
    }
    if (edit.removed !== undefined) {
      if (typeof edit.removed !== "boolean") err("removed", "must be true or false");
      else if (!edit.removed && !opts.length) err("removed", "this item wasn't found on T&T, so it can't be added");
      else sel.removed = edit.removed;
    }
  }
  return errors.length ? { errors } : { selections: next };
}

/** Lines, totals, and warnings for the current selections. */
export function summarize(research, selections, budget) {
  const lines = research.items.map((item, index) => {
    const sel = selections[index] ?? defaultSelection(item);
    const opts = optionsOf(item);
    const product = opts[sel.option] ?? opts[0] ?? null;
    const missing = !product;
    const removed = !missing && sel.removed;
    const cost = missing || removed ? 0 : round2(product.packPrice * sel.packages);
    return {
      index,
      name: item.name,
      status: item.status,
      query: item.query,
      product,
      option: sel.option,
      optionCount: opts.length,
      packages: sel.packages,
      cost,
      removed,
      missing,
      flags: product?.flags ?? [],
    };
  });

  const active = lines.filter((l) => !l.removed && !l.missing);
  const total = round2(active.reduce((s, l) => s + l.cost, 0));
  const warnings = [];

  if (total > budget) {
    const biggest = [...active].sort((a, b) => b.cost - a.cost).slice(0, 3);
    warnings.push({
      type: "budget",
      message: `$${(total - budget).toFixed(2)} over your $${budget} budget. Biggest lines: ${biggest
        .map((l) => `${l.name} ($${l.cost.toFixed(2)})`)
        .join(", ")}.`,
    });
  }
  const noLink = active.filter((l) => !l.product.url);
  if (noLink.length) {
    warnings.push({ type: "no-link", message: `The agent can't add ${noLink.map((l) => l.name).join(", ")} (no product link). Swap or remove ${noLink.length > 1 ? "them" : "it"}.` });
  }
  const check = active.filter((l) => l.option === 0 && l.status === "uncertain");
  if (check.length) {
    warnings.push({ type: "uncertain", message: `Double-check: ${check.map((l) => l.name).join(", ")}.` });
  }
  const missing = lines.filter((l) => l.missing);
  if (missing.length) {
    warnings.push({ type: "not-found", message: `Not found on T&T: ${missing.map((l) => l.name).join(", ")}. Try "Search again" with other words.` });
  }

  return {
    lines,
    total,
    budget,
    remaining: round2(budget - total),
    overBudget: total > budget,
    itemCount: active.length,
    readyForAgent: active.filter((l) => l.product.url).length,
    warnings,
  };
}

/**
 * After the whole list is re-priced, keep what the user decided where it
 * still applies: removals, and the same product (by URL) with its pack count.
 */
export function carryOver(oldResearch, oldSelections, newResearch) {
  const byName = new Map(
    (oldResearch?.items ?? []).map((item, i) => [item.name, { item, sel: oldSelections?.[i] }]),
  );
  return newResearch.items.map((item) => {
    const fresh = defaultSelection(item);
    const prev = byName.get(item.name);
    if (!prev?.sel) return fresh;
    const prevProduct = optionsOf(prev.item)[prev.sel.option];
    const opts = optionsOf(item);
    const same = prevProduct?.url ? opts.findIndex((o) => o.url === prevProduct.url) : -1;
    return {
      option: same >= 0 ? same : 0,
      packages: same >= 0 ? prev.sel.packages : fresh.packages,
      removed: Boolean(prev.sel.removed) && opts.length > 0,
    };
  });
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { defaultSelections, applyEdits, summarize, carryOver, optionsOf } from "./cart.js";

const product = (name, packPrice, packages = 1, url = `https://www.tntsupermarket.com/eng/${name.replace(/\W+/g, "-")}.html`) =>
  ({ name, packPrice, packages, cost: packPrice * packages, url, flags: [] });

const research = () => ({
  items: [
    { name: "eggs", status: "matched", query: "eggs", chosen: product("Large Eggs 18", 6.79), alternatives: [product("Large Eggs 12", 5.29, 2), product("Organic Eggs 12", 10.99, 2)] },
    { name: "firm tofu", status: "matched", query: "firm tofu", chosen: product("Firm Tofu", 1.97, 3), alternatives: [] },
    { name: "green onions", status: "uncertain", query: "green onion", chosen: product("Green Onion", 0.75, 2), alternatives: [product("Chive", 3.99)] },
    { name: "saffron", status: "not_found", query: "saffron", chosen: null, alternatives: [] },
  ],
});

test("defaults: chosen product at its suggested pack count; not-found adds nothing", () => {
  const r = research();
  const s = summarize(r, defaultSelections(r), 100);
  assert.equal(s.total, 6.79 + 5.91 + 1.5);
  assert.equal(s.itemCount, 3);
  assert.equal(s.lines[3].missing, true);
  assert.deepEqual(s.warnings.map((w) => w.type), ["uncertain", "not-found"]);
});

test("swap uses the option's pack price and suggested packs; explicit packages win", () => {
  const r = research();
  let { selections } = applyEdits(r, defaultSelections(r), [{ index: 0, name: "eggs", option: 1 }]);
  assert.deepEqual(selections[0], { option: 1, packages: 2, removed: false });
  assert.equal(summarize(r, selections, 100).lines[0].cost, 10.58);
  ({ selections } = applyEdits(r, selections, [{ index: 0, name: "eggs", option: 2, packages: 1 }]));
  assert.equal(summarize(r, selections, 100).lines[0].cost, 10.99);
});

test("remove and restore", () => {
  const r = research();
  let { selections } = applyEdits(r, defaultSelections(r), [{ index: 1, name: "firm tofu", removed: true }]);
  const s = summarize(r, selections, 100);
  assert.equal(s.lines[1].removed, true);
  assert.equal(s.lines[1].cost, 0);
  assert.equal(s.itemCount, 2);
  ({ selections } = applyEdits(r, selections, [{ index: 1, name: "firm tofu", removed: false }]));
  assert.equal(summarize(r, selections, 100).lines[1].cost, 5.91);
});

test("validation errors", () => {
  const r = research();
  const sel = defaultSelections(r);
  const fields = (edits) => applyEdits(r, sel, edits).errors?.map((e) => e.field);
  assert.deepEqual(fields([]), ["edits"]);
  assert.deepEqual(fields([{ index: 9, name: "x" }]), ["index"]);
  assert.deepEqual(fields([{ index: 0, name: "milk" }]), ["name"]);
  assert.deepEqual(fields([{ index: 0, name: "eggs", option: 3 }]), ["option"]);
  assert.deepEqual(fields([{ index: 0, name: "eggs", packages: 0 }]), ["packages"]);
  assert.deepEqual(fields([{ index: 0, name: "eggs", packages: 2.5 }]), ["packages"]);
  assert.deepEqual(fields([{ index: 0, name: "eggs", removed: "yes" }]), ["removed"]);
  assert.deepEqual(fields([{ index: 0, name: "eggs", price: 0.01 }]), ["price"]);
  assert.deepEqual(fields([{ index: 3, name: "saffron", removed: false }]), ["removed"]);
  // Nothing is applied when any edit is invalid.
  assert.equal(applyEdits(r, sel, [{ index: 0, name: "eggs", removed: true }, { index: 0, name: "eggs", option: 9 }]).selections, undefined);
});

test("over budget names the biggest lines; missing links are flagged", () => {
  const r = research();
  r.items[1].chosen.url = null;
  const s = summarize(r, defaultSelections(r), 10);
  const budget = s.warnings.find((w) => w.type === "budget");
  assert.match(budget.message, /over your \$10 budget/);
  assert.match(budget.message, /eggs \(\$6\.79\), firm tofu \(\$5\.91\), green onions \(\$1\.50\)/);
  assert.ok(s.warnings.some((w) => w.type === "no-link" && w.message.includes("firm tofu")));
  assert.equal(s.readyForAgent, 2);
});

test("carryOver keeps removals and the same product by URL", () => {
  const old = research();
  const { selections } = applyEdits(old, defaultSelections(old), [
    { index: 0, name: "eggs", option: 2, packages: 3 },
    { index: 1, name: "firm tofu", removed: true },
  ]);
  const fresh = research();
  // New pricing returns the organic eggs first this time.
  fresh.items[0].alternatives.unshift(fresh.items[0].chosen);
  fresh.items[0].chosen = optionsOf(old.items[0])[2];
  fresh.items[0].alternatives = fresh.items[0].alternatives.filter((a) => a.url !== fresh.items[0].chosen.url);
  const carried = carryOver(old, selections, fresh);
  assert.deepEqual(carried[0], { option: 0, packages: 3, removed: false });
  assert.equal(carried[1].removed, true);
  assert.deepEqual(carried[2], { option: 0, packages: 2, removed: false });
  assert.equal(carried[3].removed, false); // not found: nothing to remove
});

