import { useCallback } from "react";
import { useAuth0 } from "@auth0/auth0-react";

export class ApiError extends Error {
  constructor(status, body) {
    super(body?.error ?? `HTTP ${status}`);
    this.status = status;
    this.body = body;
  }
}

const NEEDS_INTERACTION = new Set(["consent_required", "login_required", "interaction_required"]);

/**
 * Returns a fetch wrapper that attaches the user's Auth0 access token.
 * Pass `scope` to ask for an extra permission just for this call (step-up):
 * Auth0 shows a consent popup the first time if needed.
 */
export function useApi() {
  const { getAccessTokenSilently, getAccessTokenWithPopup } = useAuth0();
  return useCallback(
    async (path, { method = "GET", body, scope } = {}) => {
      let token;
      if (scope) {
        const authorizationParams = { scope: `openid profile email read:profile write:profile ${scope}` };
        try {
          token = await getAccessTokenSilently({ authorizationParams, cacheMode: "off" });
        } catch (err) {
          if (!NEEDS_INTERACTION.has(err.error)) throw err;
          token = await getAccessTokenWithPopup({ authorizationParams });
        }
      } else {
        token = await getAccessTokenSilently();
      }
      const res = await fetch(`/api${path}`, {
        method,
        headers: {
          Authorization: `Bearer ${token}`,
          ...(body !== undefined && { "Content-Type": "application/json" }),
        },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      const json = await res.json().catch(() => null);
      if (!res.ok) throw new ApiError(res.status, json);
      return json;
    },
    [getAccessTokenSilently, getAccessTokenWithPopup],
  );
}

import { useState } from "react";

const money = (x) => `$${x.toFixed(2)}`;

/**
 * The consequential step. Asks Auth0 for the build:cart permission only now,
 * and sends back the exact total and item count the user is looking at so the
 * server can refuse if the cart changed underneath them.
 */
export default function ApproveCart({ task, setTask, api, reload }) {
  const review = task.review;
  const [agreed, setAgreed] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const rebuild = task.status === "built";
  if (!review || review.readyForAgent === 0) return null;

  async function approve() {
    setBusy(true);
    setError("");
    try {
      const { task: t } = await api(`/shopping-tasks/${task.id}/build-cart`, {
        method: "POST",
        scope: "build:cart",
        body: { expectedTotal: review.total, expectedItems: review.itemCount },
      });
      setTask(t);
      reload(t.id);
    } catch (err) {
      if (err.body?.error === "stale_review") reload(task.id);
      setError(
        err.error === "access_denied" || err.status === 403
          ? "CartPilot needs your permission to build the cart. Approve again and allow access."
          : err.message === "Popup closed" || err.error === "cancelled"
            ? "The permission window was closed. Approve again when you're ready."
            : err.body?.message ?? "Couldn't start building your cart.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="approve" aria-labelledby="approve-h">
      <h3 id="approve-h">{rebuild ? "Rebuild your T&T cart" : "Approve & build your T&T cart"}</h3>
      <p>
        CartPilot's agent will add <strong>{review.readyForAgent} item{review.readyForAgent === 1 ? "" : "s"}</strong>{" "}
        (about <strong>{money(review.total)}</strong>) to your T&amp;T cart, setting each to the quantity you chose.
        {rebuild && " Items already in your cart are set to these quantities, not added again."}
      </p>
      <label className="agree">
        <input type="checkbox" checked={agreed} onChange={(e) => setAgreed(e.target.checked)} />
        <span>I approve. The agent will <strong>not</strong> check out or pay. I'll finish checkout on T&amp;T myself.</span>
      </label>
      <div className="actions">
        <button type="button" disabled={!agreed || busy} onClick={approve}>
          {busy ? "Starting the agent…" : rebuild ? "Rebuild cart" : "Approve & build cart"}
        </button>
        <span className="muted">You'll be asked to grant CartPilot the "build cart" permission.</span>
      </div>
      {error && <p className="error" role="alert">{error}</p>}
    </section>
  );
}

const OUTCOME = {
  pending: { label: "Working…", cls: "chip-muted" },
  added: { label: "Added", cls: "chip-ok" },
  updated: { label: "Quantity set", cls: "chip-ok" },
  out_of_stock: { label: "Out of stock", cls: "chip-bad" },
  unavailable: { label: "Unavailable", cls: "chip-bad" },
  failed: { label: "Failed", cls: "chip-bad" },
};
const STATUS_TEXT = {
  building: "The agent is adding your items to T&T…",
  built: "Your T&T cart is ready.",
  partial: "Most items are in your T&T cart. Check the ones below.",
  failed: "The agent couldn't add your items.",
};
const T_AND_T_HOME = "https://www.tntsupermarket.com/eng/";

export default function CartBuild({ cartRun, building }) {
  if (!cartRun) return null;
  const live = cartRun.runs?.filter((r) => r.status !== "COMPLETED" && r.status !== "FAILED" && r.status !== "CANCELLED") ?? [];
  const status = building ? "building" : cartRun.status;

  return (
    <section className="cart-build" aria-live="polite">
      <h3>{STATUS_TEXT[status] ?? "Cart build"}</h3>

      {building && (
        <div className="live-grid">
          {(live.length ? live : cartRun.runs ?? []).slice(0, 2).map((r) => (
            <div key={r.batch} className="live-frame">
              {r.streamingUrl ? (
                <iframe src={r.streamingUrl} title={`TinyFish agent ${r.batch + 1} live browser`} sandbox="allow-scripts allow-same-origin" />
              ) : (
                <div className="live-placeholder">
                  <span className="spinner" aria-hidden="true" /> Starting a browser signed in to T&amp;T…
                </div>
              )}
              <span className="muted small">
                Agent {r.batch + 1} · {r.status.toLowerCase()}{r.steps ? ` · ${r.steps} steps` : ""}
              </span>
            </div>
          ))}
        </div>
      )}

      <ul className="outcomes">
        {cartRun.items.map((it) => (
          <li key={it.url}>
            <div className="outcome-head">
              <span>
                <span className="item-name">{it.name}</span>
                <span className="muted"> · {it.packages} × {it.productName}</span>
              </span>
              <span className={`chip ${OUTCOME[it.outcome]?.cls ?? "chip-muted"}`}>
                {it.outcome === "pending" && building && <span className="spinner" aria-hidden="true" />}
                {OUTCOME[it.outcome]?.label ?? it.outcome}
              </span>
            </div>
            {it.note && it.outcome !== "added" && it.outcome !== "updated" && <p className="muted small">{it.note}</p>}
            {it.note && /expected/.test(it.note) && (it.outcome === "added" || it.outcome === "updated") && (
              <p className="error small">{it.note}</p>
            )}
          </li>
        ))}
      </ul>

      {cartRun.skipped?.length > 0 && (
        <p className="muted small">Not sent to the agent: {cartRun.skipped.map((s) => `${s.name} (${s.reason})`).join(", ")}.</p>
      )}

      {!building && (
        <div className="build-done">
          {cartRun.counts && (
            <p>
              {cartRun.counts.added} added
              {cartRun.counts.outOfStock ? ` · ${cartRun.counts.outOfStock} out of stock` : ""}
              {cartRun.counts.failed ? ` · ${cartRun.counts.failed} failed` : ""}
              {cartRun.cartSubtotal && <> · T&amp;T cart subtotal <strong>{cartRun.cartSubtotal}</strong></>}
            </p>
          )}
          <div className="actions">
            <a className="button" href={cartRun.cartUrl ?? T_AND_T_HOME} target="_blank" rel="noreferrer">Open my T&amp;T cart</a>
            <span className="muted">Choose delivery or pickup and check out on T&amp;T yourself. CartPilot never pays.</span>
          </div>
          {cartRun.cartSubtotal && (
            <p className="muted small">The T&amp;T subtotal includes anything that was already in your cart.</p>
          )}
          <p className="muted small">
            Approved {new Date(cartRun.approval.approvedAt).toLocaleString()} with the build:cart permission.{" "}
            {cartRun.runs?.filter((r) => r.runId).map((r, i) => (
              <a key={r.runId} href={`https://agent.tinyfish.ai/runs/${encodeURIComponent(r.runId)}`} target="_blank" rel="noreferrer">
                {i ? ", " : ""}TinyFish run {r.batch + 1}
              </a>
            ))}
          </p>
        </div>
      )}
    </section>
  );
}

result.output:
    .then(({ tasks }) => tasks[0] && load(tasks[0].id))
    .catch(() => {});
  return () => clearTimeout(timer.current);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [api]);

async function load(id) {
  try {
    const { task } = await api(`/shopping-tasks/${id}`);
    setTask(task);
    if (task.status === "planning" || task.status === "researching") {
      timer.current = setTimeout(() => load(id), POLL_MS);
    }
  } catch (e) {
    setError(e.body?.message ?? "Couldn't load the plan.");
  }
}

async function start(e) {
  e.preventDefault();
  setError("");
  try {
    const { task } = await api("/shopping-tasks", { method: "POST", body: { note } });
    setTask(task);
    timer.current = setTimeout(() => load(task.id), POLL_MS);
  } catch (err) {
    setError(err.body?.message ?? (err.body?.fields ? Object.values(err.body.fields).join(" ") : "Couldn't start planning."));
  }
}

async function price() {
  setError("");
  try {
    const { task: t } = await api(`/shopping-tasks/${task.id}/research`, { method: "POST" });
    setTask(t);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => load(t.id), POLL_MS);
  } catch (err) {
    setError(err.body?.message ?? "Couldn't start the price search.");
  }
}

const planning = task?.status === "planning";
const busy = planning || task?.status === "researching";
const hasPlan = task && ["planned", "researching", "priced"].includes(task.status);

return (
  <section className="card">
    <h2>Plan my groceries</h2>
    {!profileSaved ? (
      <p className="muted">Save your profile first. The planner uses your budget, diet, and pantry.</p>
    ) : (
      <form onSubmit={start}>
        <label className="field">
          <span>Anything specific this time? (optional)</span>
          <textarea rows="2" maxLength={500} value={note} onChange={(e) => setNote(e.target.value)}
            placeholder="e.g. more vegetables, one fish dinner, nothing spicy" />
        </label>
        <div className="actions">
          <button type="submit" disabled={busy}>{planning ? "Planning…" : task ? "Plan again" : "Plan my groceries"}</button>
          {planning && <span className="muted">The planner usually takes 10–30 seconds.</span>}
          {error && <span className="error">{error}</span>}
        </div>
      </form>
    )}

    {task?.status === "failed" && <p className="error">{task.error}</p>}
    {hasPlan && (
      <PlanResult result={task.result} input={task.input}>
        <div className="price-cta">
          {task.status === "researching" ? (
            <p className="muted"><span className="spinner" aria-hidden="true" /> TinyFish is searching T&amp;T for each item… usually 30–60 seconds.</p>
          ) : (
            <div className="actions">
              <button type="button" className={task.status === "priced" ? "secondary" : ""} onClick={price}>
                {task.status === "priced" ? "Refresh T&T prices" : "Find prices on T&T"}
              </button>
              {task.status === "priced" && (
                <span className="muted">Re-checking prices keeps your removals and picks where possible.</span>
              )}
              {task.error && <span className="error">{task.error}</span>}
            </div>
          )}
        </div>
        {task.result.research && (
          <ReviewCart task={task} setTask={setTask} api={api} stale={task.status === "researching"} />
        )}
      </PlanResult>
    )}
  </section>
);

