// Live A/B: same 6 items, concurrency from argv[2]. Run from the repo root:
//   node --env-file=.env.local <this file> 1
import { createAgentClient } from "/Users/mglean/HackWestern/server/cart/agent.js";
import { planCartRun, runCartBuild } from "/Users/mglean/HackWestern/server/cart/buildCart.js";

const concurrency = Number(process.argv[2] ?? 1);
const B = "https://www.tntsupermarket.com/eng/";
const L = (index, name, query, productName, slug, perLb = false) =>
  ({ index, name, query, removed: false, missing: false, packages: 1, cost: 1, product: { name: productName, url: B + slug, perLb } });
const review = { lines: [
  L(0, "green onions", "green onion", "Green Onion (1bunch)", "05014501-green-onion.html"),
  L(1, "firm tofu", "firm tofu", "Superior Natural Firm Tofu (454g)", "51280001-superior-firm-tofu.html"),
  L(2, "garlic", "garlic", "Garlic 3pcs", "05008501-garlic.html"),
  L(3, "eggs", "large eggs", "Burnbrae Farms Large Eggs (12pcs)", "63719801-burnbrae-far-large-white-eggs.html"),
  L(4, "ground pork", "ground pork", "Ground Pork - Regular (~2lb)", "03011701-ground-pork-regular.html", true),
  L(5, "chicken thighs", "chicken thigh", "Fresh Chicken Thigh Boneless Skinless Value Pack (2.5lb)", "03030001-fresh-chicken-thigh-boneless-skinless-value-pack.html", true),
] };

const run = planCartRun(review, { sub: "ab-test", approvedAt: new Date().toISOString(), total: 6, itemCount: 6 });
const t = Date.now();
let last = "";
await runCartBuild(run, {
  agent: createAgentClient({ apiKey: process.env.TINYFISH_API_KEY }),
  profileId: process.env.TINYFISH_PROFILE_ID,
  concurrency,
  pollMs: 5000,
  save: (c) => {
    const s = c.runs.map((r) => `#${r.batch}a${r.attempt}:${r.status}/${r.steps ?? "-"}`).join(" ");
    if (s !== last) {
      last = s;
      console.log(`[${((Date.now() - t) / 1000).toFixed(0)}s]`, s);
    }
  },
});
console.log(JSON.stringify({
  concurrency,
  wall: ((Date.now() - t) / 1000).toFixed(0) + "s",
  status: run.status,
  counts: run.counts,
  steps: run.steps,
  items: run.items.map((i) => [i.name, i.outcome, i.quantityInCart, (i.note ?? "").slice(0, 80)]),
  runs: run.runs.map((r) => [r.runId, r.attempt, r.status, r.steps, r.error]),
}, null, 1));

